<section id="payables-view" hidden aria-labelledby="payables-title">
    <div class="section-heading"><div><h1 id="payables-title">Cuentas por pagar</h1><p class="hint">Compras recibidas, saldo por proveedor e historial de pagos. Registrar un pago no ejecuta transferencias bancarias.</p></div></div>
    <p id="payables-message" role="status" aria-live="polite"></p>
    <section id="payables-list"><form id="payables-filter" class="report-filters"><div><label for="payables-search">Folio, proveedor o factura</label><input id="payables-search" type="search" maxlength="100"></div><div><label for="payables-provider">Proveedor</label><select id="payables-provider"></select></div><div><label for="payables-state">Estado del pago</label><select id="payables-state"><option value="todos">Todos</option><option value="pendiente">Con saldo pendiente</option><option value="vencida">Vencidas</option><option value="pagada">Pagadas</option><option value="por_conciliar">Por conciliar</option></select></div><button class="primary" data-icon="magnifying-glass" type="submit">Consultar</button></form><p id="payables-summary"></p>
        <h2>Saldo por proveedor</h2><div class="table-scroll"><table><thead><tr><th>Proveedor</th><th>Compras</th><th>Saldo confirmado</th><th>Por conciliar</th></tr></thead><tbody id="payables-vendors"></tbody></table></div>
        <h2>Compras del filtro</h2><div class="table-scroll"><table><thead><tr><th>Folio / proveedor</th><th>Condición</th><th>Total</th><th>Saldo pendiente</th><th>Vencimiento</th><th>Acciones</th></tr></thead><tbody id="payables-rows"></tbody></table></div><button id="payables-more" class="secondary" type="button" hidden>Cargar más compras</button>
    </section>
    <section id="payable-detail" hidden><div class="section-heading"><h2 id="payable-detail-title"></h2><button id="payable-back" class="secondary" data-icon="arrow-left" type="button">Volver a cuentas</button></div><p id="payable-summary"></p><p id="payable-condition" class="hint"></p>
        <form id="payable-reconcile" hidden><h3>Confirmar saldo inicial</h3><p class="hint">Esta compra no tiene un saldo inicial confirmado. Revisa tus registros e indica cuánto falta pagar. El importe ya pagado se reconoce como antecedente; no retira dinero de ninguna caja ni crea pagos históricos ficticios. Solo el administrador puede confirmar este saldo, una sola vez.</p><fieldset id="payable-reconcile-fields" class="adjust-fields"><div class="product-fields"><div><label for="payable-initial">Saldo que falta pagar</label><input id="payable-initial" type="number" min="0" step=".01" required></div><div><label for="payable-initial-mode">Condición original</label><select id="payable-initial-mode"><option value="credito">Crédito</option><option value="contado">Contado</option></select></div><div><label for="payable-initial-due">Vencimiento del saldo a crédito</label><input id="payable-initial-due" type="date" min="2023-01-01"></div><div class="full-width"><label for="payable-initial-note">Motivo y registros revisados</label><textarea id="payable-initial-note" maxlength="300" rows="2" required></textarea></div></div><label class="check-label"><input id="payable-initial-confirm" type="checkbox" required> Confirmo que revisé el saldo. Esta conciliación no podrá modificarse.</label></fieldset><p id="payable-reconcile-error" class="message" role="alert"></p><button id="payable-reconcile-save" class="primary" data-icon="check" type="submit">Confirmar saldo</button></form>
        <p id="payable-reconciliation" class="hint"></p>
        <form id="payable-payment"><fieldset id="payable-payment-fields" class="adjust-fields"><h3>Registrar pago al proveedor</h3><p id="payable-payment-help" class="hint"></p><div class="product-fields"><div><label for="payable-origin">Origen del dinero</label><select id="payable-origin"><option value="caja">Efectivo de mi caja</option><option value="externo">Otra cuenta o fondos externos</option></select></div><div id="payable-turn-field"><label for="payable-turn">Mi turno abierto</label><select id="payable-turn"></select></div><div id="payable-account-field"><label for="payable-account">Cuenta o fondos utilizados</label><input id="payable-account" maxlength="100" placeholder="Ej. Cuenta bancaria del negocio"></div><div><label for="payable-method">Método de pago</label><select id="payable-method" required></select></div><div><label for="payable-amount">Importe pagado</label><input id="payable-amount" type="number" min=".01" step=".01" required></div><div><label for="payable-reference">Referencia del pago (opcional)</label><input id="payable-reference" maxlength="100"></div><div class="full-width"><label for="payable-note">Concepto o motivo</label><textarea id="payable-note" maxlength="300" rows="2" required></textarea></div></div><p id="payable-origin-help" class="hint"></p><label class="check-label"><input id="payable-confirm" type="checkbox" required> Confirmo que realicé este pago y quiero registrarlo en esta compra.</label></fieldset><p id="payable-error" class="message" role="alert"></p><button id="payable-pay" class="primary" data-icon="check" type="submit">Registrar pago</button></form>
        <h3>Historial de pagos</h3><div id="payable-history"></div>
    </section><div id="payable-receipt" class="ticket-paper" hidden></div>
</section>
